Xi=np.hstack([np.ones((len(X),1)),X])
Xs=(X-X.mean(0))/X.std(0)

def conv(X,Y,lr):
    th=np.zeros(X.shape[1]); it=0; d=np.inf
    with np.errstate(over='ignore',invalid='ignore'):
        while True:
            it+=1; prev=th.copy()
            p=1/(1+np.exp(-X.dot(th))); g=X.T.dot(Y-p); th=th+lr*g
            d=np.linalg.norm(prev-th)
            if d<1e-15 or it>100000: break
    return it,d,np.isfinite(th).all(),np.linalg.norm(th)
for name,A in [('raw',X),('intercept',Xi),('std',Xs)]:
    for lr in [40,50,100,200,500]:
        print(name,'lr',lr,conv(A,Y,lr))
